import { basename } from 'node:path';
import { getBinCommand, getRunningPackageManager } from '@sanity/cli-core/package-manager';
import * as find from 'empathic/find';
/**
 * Lockfile names in priority order
 */
const LOCKFILES = {
    'pnpm-lock.yaml': 'pnpm',
    'yarn.lock': 'yarn',
    'bun.lock': 'bun',
    'bun.lockb': 'bun',
    'package-lock.json': 'npm',
};
const LOCKFILE_NAMES = Object.keys(LOCKFILES);
/** Minimal user agents, so the lockfile path reuses the same command mapping. */
const SYNTHETIC_USER_AGENTS = {
    npm: 'npm/0',
    pnpm: 'pnpm/0',
    yarn: 'yarn/0',
    bun: 'bun/0',
};
const lockfileCache = new Map();
/** Find the package manager a lockfile at or above `dir` implies. */
function detectFromLockfile(dir) {
    if (lockfileCache.has(dir))
        return lockfileCache.get(dir);
    const found = find.any(LOCKFILE_NAMES, { cwd: dir });
    const manager = found ? LOCKFILES[basename(found)] : undefined;
    lockfileCache.set(dir, manager);
    return manager;
}
/**
 * Detect the package manager for a project.
 *
 * `npm_config_user_agent` is first then lockfile detection.
 */
export function detectPackageManager(dir = process.cwd()) {
    return getRunningPackageManager() ?? detectFromLockfile(dir);
}
/**
 * The command that runs this CLI, matched to the detected package manager.
 * Falls back to `npx`
 *
 * Yarn is weird: detected from a lockfile alone also falls bac
 * lockfile name does not differentiate Yarn 1 vs Yarn 2+
 */
export function runCommand(bin, dir) {
    const running = getRunningPackageManager();
    if (running)
        return getBinCommand({ bin });
    const fromLockfile = detectFromLockfile(dir ?? process.cwd());
    if (!fromLockfile || fromLockfile === 'yarn')
        return `npx ${bin}`;
    return getBinCommand({ bin, userAgent: SYNTHETIC_USER_AGENTS[fromLockfile] });
}
/** The command that installs dependencies, matched to the detected package manager. */
export function installCommand(dir) {
    return `${detectPackageManager(dir) ?? 'npm'} install`;
}
/** Clear the lockfile lookup cache. Tests use this after they move fixtures. */
export function resetPackageManagerCache() {
    lockfileCache.clear();
}
